SELECT

FROM stock_in_record
WHERE 1=1

    AND batch_number LIKE CONCAT('%', #{keyword}, '%')


    AND product_id = #{productId}


    AND status = #{status}


    AND create_time >= #{startDate}


    AND create_time <= #{endDate}

ORDER BY create_time DESC
LIMIT #{offset}, #{pageSize}

