mapper.select:
SELECT sir.supplier_id as supplier_id, sup.name as supplier_name, sup.contact_person as contact_person, sup.contact_phone as contact_phone, COUNT(sir.id) as supply_count, SUM(sir.quantity) as total_quantity, SUM(sir.total_price) as total_amount FROM stock_in_record sir LEFT JOIN supplier sup ON sup.id = sir.supplier_id WHERE 1=1
AND sir.create_time >= #{startDate}
AND sir.create_time <= #{endDate}
GROUP BY sir.supplier_id, sup.name, sup.contact_person, sup.contact_phone ORDER BY total_amount DESC
